<?php
require_once dirname(__DIR__).'/config/database.php';require_once dirname(__DIR__).'/includes/layout.php';require_login('admin');
$students=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='student'")->fetchColumn();$courses=(int)$pdo->query("SELECT COUNT(*) FROM courses WHERE status='active'")->fetchColumn();$paid=(float)$pdo->query("SELECT COALESCE(SUM(amount_kes),0) FROM payments WHERE status='success'")->fetchColumn();$pending=(int)$pdo->query("SELECT COUNT(*) FROM payments WHERE status='pending'")->fetchColumn();$recent=$pdo->query('SELECT p.*,u.full_name,c.title FROM payments p JOIN users u ON u.id=p.user_id JOIN courses c ON c.id=p.course_id ORDER BY p.created_at DESC LIMIT 7')->fetchAll();
start_page('Administrator overview','dashboard'); ?><div class="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div class="stat-card"><p class="stat-label">Registered students</p><p class="stat-value"><?= $students ?></p></div><div class="stat-card"><p class="stat-label">Active courses</p><p class="stat-value"><?= $courses ?></p></div><div class="stat-card"><p class="stat-label">Confirmed payments</p><p class="stat-value">KSh <?= number_format($paid,2) ?></p></div><div class="stat-card"><p class="stat-label">Awaiting confirmation</p><p class="stat-value"><?= $pending ?></p></div></div><section class="mb-6 grid gap-4 md:grid-cols-3"><a class="card hover:border-teal-500" href="<?= e(app_url('admin/students.php')) ?>"><span class="course-code">PEOPLE</span><h2 class="card-title mt-2">Manage students</h2><p class="muted mt-2">View student accounts and access status.</p></a><a class="card hover:border-teal-500" href="<?= e(app_url('admin/courses.php')) ?>"><span class="course-code">CURRICULUM</span><h2 class="card-title mt-2">Manage courses</h2><p class="muted mt-2">Create, edit and archive course listings.</p></a><a class="card hover:border-teal-500" href="<?= e(app_url('admin/payments.php')) ?>"><span class="course-code">FINANCE</span><h2 class="card-title mt-2">Payment records</h2><p class="muted mt-2">Review provider, status and payment references.</p></a></section><div class="mb-3 flex items-center justify-between"><h2 class="card-title">Recent transactions</h2><a class="text-sm font-bold text-teal-700" href="<?= e(app_url('admin/payments.php')) ?>">All payments →</a></div><div class="table-wrap"><table><thead><tr><th>Student</th><th>Course</th><th>Method</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($recent as $p): ?><tr><td class="font-semibold"><?= e($p['full_name']) ?></td><td><?= e($p['title']) ?></td><td><?= e(strtoupper($p['provider'])) ?></td><td>KSh <?= number_format((float)$p['amount_kes'],2) ?></td><td><span class="badge badge-<?= e($p['status']==='success'?'success':($p['status']==='failed'?'failed':'pending')) ?>"><?= e($p['status']) ?></span></td><td><?= e(date('M j, Y',strtotime($p['created_at']))) ?></td></tr><?php endforeach ?><?php if(!$recent): ?><tr><td colspan="6" class="py-8 text-center text-slate-500">No transactions recorded yet.</td></tr><?php endif ?></tbody></table></div><?php end_page(); ?>
